(()=>{const header=document.getElementById('site-header'),toggle=document.getElementById('nav-toggle'),nav=document.getElementById('site-navigation');if(!header||!toggle||!nav)return;const small=matchMedia('(max-width:1250px)');header.classList.add('nav-ready');function setOpen(open,focus=false){header.classList.toggle('nav-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.lastElementChild.textContent=open?'×':'☰';if(focus)toggle.focus()}toggle.addEventListener('click',()=>setOpen(!header.classList.contains('nav-open')));nav.addEventListener('click',e=>{if(e.target.closest('a,button')&&small.matches)setOpen(false,e.target.closest('button')!==null)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&header.classList.contains('nav-open')){e.preventDefault();setOpen(false,true)}});document.addEventListener('click',e=>{if(!header.contains(e.target)&&header.classList.contains('nav-open'))setOpen(false)});small.addEventListener('change',()=>setOpen(false));})();
